def _get_incdec_value(number, incdec, url, count):
    """Replace a matched number while retaining its original zero padding."""
    val = int(number)
    if incdec == 'decrement':
        if val < count:
            raise IncDecError("Can't decrement {}!".format(val), url)
        val -= count
    elif incdec == 'increment':
        val += count
    else:
        raise ValueError("Invalid value {} for incdec!".format(incdec))
    replacement = str(val)
    if number.startswith('0'):
        replacement = replacement.zfill(len(number))
    return replacement


def _incdec_match(value):
    """Find the first number outside percent-encoded triplets."""
    encoded_positions = set()
    for escape in re.finditer(r'%[0-9A-Fa-f]{2}', value):
        encoded_positions.update(range(escape.start() + 1, escape.end()))
    for match in re.finditer(r'[0-9]+', value):
        # A number can start inside an escape and continue after it.
        start = match.start()
        while start < match.end() and start in encoded_positions:
            start += 1
        if start < match.end():
            return start, match.end()
    return None


def incdec_number(url, incdec, count=1, segments=None):
    """Find a number in the url and increment or decrement it.

    Args:
        url: The current url
        incdec: Either 'increment' or 'decrement'
        count: The number to increment or decrement by
        segments: A set of URL segments to search. Valid segments are:
                  'host', 'path', 'query', 'anchor'. 'port' is accepted but
                  never changed. Default: {'path'}.

    Return:
        The new url with the number incremented/decremented.

    Raises IncDecError if the url contains no number.
    """
    if not url.isValid():
        raise InvalidUrlError(url)

    if incdec not in {'increment', 'decrement'}:
        raise ValueError("Invalid value {} for incdec!".format(incdec))
    if isinstance(count, bool) or not isinstance(count, int) or count <= 0:
        raise ValueError("count must be a positive integer")

    if segments is None:
        segments = {'path'}
    valid_segments = {'host', 'port', 'path', 'query', 'anchor'}
    if segments - valid_segments:
        extra_elements = segments - valid_segments
        raise IncDecError("Invalid segments: {}".format(
            ', '.join(extra_elements)), url)

    # Make a copy of the QUrl so we don't modify the original
    url = QUrl(url)
    # Search priority for navigation. FullyEncoded keeps escapes intact.
    segment_modifiers = [
        ('path', lambda: url.path(QUrl.FullyEncoded),
         lambda value: url.setPath(value, QUrl.StrictMode)),
        ('query', lambda: url.query(QUrl.FullyEncoded),
         lambda value: url.setQuery(value, QUrl.StrictMode)),
        ('anchor', lambda: url.fragment(QUrl.FullyEncoded),
         lambda value: url.setFragment(value, QUrl.StrictMode)),
        ('host', lambda: url.host(QUrl.FullyEncoded), url.setHost),
    ]
    for segment, getter, setter in segment_modifiers:
        if segment not in segments:
            continue

        value = getter()
        found = _incdec_match(value)
        if found is None:
            continue
        start, end = found
        replacement = _get_incdec_value(value[start:end], incdec, url, count)
        setter(value[:start] + replacement + value[end:])
        return url

    raise IncDecError("No number found in URL!", url)


def file_url(path):
    """Return a file:// url (as string) to the given local path.

    Arguments:
        path: The absolute path to the local file
    """
    return QUrl.fromLocalFile(path).toString(QUrl.FullyEncoded)


